import{_ as e,c as a,a2 as p,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第九十一章 什么人才是真正的修行人？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/91第九十一章 什么人才是真正的修行人.md","filePath":"meditation/巴利文大藏经/91第九十一章 什么人才是真正的修行人.md"}'),o={name:"meditation/巴利文大藏经/91第九十一章 什么人才是真正的修行人.md"};function r(n,t,i,s,d,c){return _(),a("div",null,t[0]||(t[0]=[p('<h1 id="第九十一章-什么人才是真正的修行人" tabindex="-1">第九十一章 什么人才是真正的修行人？ <a class="header-anchor" href="#第九十一章-什么人才是真正的修行人" aria-label="Permalink to &quot;第九十一章 什么人才是真正的修行人？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>8.沙门婆罗门品</p><p>相应部12相应71经/老死经(因缘相应/因缘篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，任何的出家人、婆罗门修行人他们不明白缘起法（缘起法解释，见第四十八章、第四十九章），他们不明白「老死」，不明白「老死」的起因、形成、聚集。不明白「老死」的灭尽，不明白灭尽「老死」的修行方法，弟子们对于如来来说，他们就不是真正的出家人，他们就不是真正的婆罗门修行人，他们就不是被同意出家的人，他们就不是被同意成为婆罗门的人，这些人也无法用自己开启的智慧来证明自己已经证悟了解脱的果位。他们这一世无法达到修行解脱的目标，他们这一世无法灭除所有的贪欲、愤怒、愚痴。他们这一世无法灭除一切的烦恼和痛苦，他们这一世无法通过修行进入涅槃的境界。</p><p>弟子们，任何的出家人、婆罗门修行人他们明白了缘起法（缘起法解释，见第四十八章、第四十九章），他们明白了「老死」，明白了「老死」的起因、形成、聚集。明白了「老死」的灭尽，明白了灭尽「老死」的修行方法，弟子们对于如来来说，他们就是真正的出家人，他们就是真正的婆罗门修行人，他们就是被同意出家的人，他们就是被同意成为婆罗门的人，这些人能够用自己开启的智慧来证明自己已经证悟了解脱的果位。他们这一世能够达到修行解脱的目标，他们这一世能够灭除所有的贪欲、愤怒、愚痴。他们这一世能够灭除一切的烦恼和痛苦。他们这一世能够通过修行进入涅槃的境界。</p><p>弟子们，同样的道理，任何的出家人、婆罗门修行人他们不明白缘起法（缘起法解释，见第四十八章、第四十九章），他们不明白「生」、「有」、「取」、「爱」、「受」、「触」、「六处」、「名色」、「识」、「行」、「无明」，不明白「生」、「有」、「取」、「爱」、「受」、「触」、「六处」、「名色」、「识」、「行」、「无明」的起因、形成、聚集。不明白「生」、「有」、「取」、「爱」、「受」、「触」、「六处」、「名色」、「识」、「行」、「无明」的灭尽，不明白灭尽「生」、「有」、「取」、「爱」、「受」、「触」、「六处」、「名色」、「识」、「行」、「无明」的修行方法，弟子们对于如来来说，他们就不是真正的出家人，他们就不是真正的婆罗门修行人，他们就不是被同意出家的人，他们就不是被同意成为婆罗门的人，这些人也无法用自己开启的智慧来证明自己已经证悟了解脱的果位。他们这一世无法达到修行解脱的目标，他们这一世无法灭除所有的贪欲、愤怒、愚痴。他们这一世无法灭除一切的烦恼和痛苦，他们这一世无法通过修行进入涅槃的境界。</p><p>弟子们，任何的出家人、婆罗门修行人他们明白了缘起法（缘起法解释，见第四十八章、第四十九章），他们明白了「生」、「有」、「取」、「爱」、「受」、「触」、「六处」、「名色」、「识」、「行」、「无明」，明白了「老死」的起因、形成、聚集。明白了「生」、「有」、「取」、「爱」、「受」、「触」、「六处」、「名色」、「识」、「行」、「无明」的灭尽，明白了灭尽「生」、「有」、「取」、「爱」、「受」、「触」、「六处」、「名色」、「识」、「行」、「无明」的修行方法，弟子们对于如来来说，他们就是真正的出家人，他们就是真正的婆罗门修行人，他们就是被同意出家的人，他们就是被同意成为婆罗门的人，这些人能够用自己开启的智慧来证明自己已经证悟了解脱的果位。他们这一世能够达到修行解脱的目标，他们这一世能够灭除所有的贪欲、愤怒、愚痴。他们这一世能够灭除一切的烦恼和痛苦。他们这一世能够通过修行进入涅槃的境界。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',9)]))}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
